    69	export async function ensureModel(name: string, deps: EnsureModelDependencies): Promise<EnsureOutcome> {
    70	  const entry = deps.catalog.byName(name)
    71	  if (entry === undefined) return { status: 'not_declared', name }
    72	  const resolution = await deps.resolver.resolve(entry.artifact)
    73	  if (resolution.status !== 'resolved') return { status: 'not_materializable', name, reason: resolution.reason }
    74	
    75	  const materialized = await materialize(entry.artifact, resolution.pinned, deps)
    76	  if (!materialized.ok) return { status: 'failed', name, stage: 'materialize', reason: materialized.reason, downloaded: false, installed: false }
    77	  const { downloaded } = materialized.value
    78	
    79	  const reconciled = await reconcileRuntime(name, materialized.value, deps.installer)
    80	  if (!reconciled.ok) return { status: 'failed', name, stage: 'install', reason: reconciled.reason, downloaded, installed: false }
    81	  const { installed, state } = reconciled.value
    82	
    83	  const evidence = { catalogSha256: entry.artifact.sha256, materializedSha256: materialized.value.sha256, runtimeSha256: state?.contentSha256 ?? '' }
    84	  if (!isReady(evidence)) return { status: 'failed', name, stage: 'verify', reason: mismatchReason(name, evidence), downloaded, installed }
