    88	async function materialize(artifact: CatalogArtifact, pinned: PinnedModelArtifact, deps: EnsureModelDependencies): Promise<StepResult<Materialized>> {
    89	  const outcome = await materializeArtifact({ artifact, pinned, cacheDir: deps.cacheDir, fetcher: deps.fetcher })
    90	  if ('reason' in outcome) return { ok: false, reason: outcome.reason }
    91	  // `materializeArtifact` sólo devuelve `cached`/`fetched` tras medir el
    92	  // sha256 del archivo publicado: ese es el digest materializado.
    93	  return { ok: true, value: { path: outcome.path, sha256: outcome.sha256, downloaded: outcome.status === 'fetched' } }
    94	}
