 1	/**
 2	 * Materialización verificada de un artefacto de modelo en la caché local
 3	 * (TASK-THYROX-0729).
 4	 *
 5	 * La caché es reconstruible y no es autoridad: la autoridad es el artefacto
 6	 * permanente, y el contenido válido es el que tiene el sha256 que el catálogo
 7	 * declara. Por eso una entrada en caché se vuelve a verificar antes de usarla,
 8	 * y una que no coincide se descarta y se reconstruye.
 9	 *
10	 * La descarga escribe en un temporal hermano y sólo un `rename` atómico tras
11	 * verificar el sha256 la publica en la ruta por digest que leen los
12	 * consumidores: una descarga cortada o con otro contenido nunca parece un
13	 * GGUF materializado. Quién descarga es un `ArtifactFetcher`: en producción,
14	 * un trabajo de la primitiva de Podman sin credencial.
15	 */
16	import { mkdir, rename, rm, stat } from 'node:fs/promises'
17	import { join } from 'node:path'
18	
19	import type { CatalogArtifact } from '@thyrox/model-artifacts/catalogEntry.ts'
20	import type { PinnedModelArtifact } from '@thyrox/model-artifacts/modelArtifactResolver.ts'
21	
22	import { sha256OfFile } from './sha256File.js'
23	
24	export type FetchOutcome =
25	  | { readonly status: 'fetched' }
26	  | { readonly status: 'failed'; readonly reason: string }
27	
28	/** Escribe el blob GGUF de `pinned` en `destination`; no verifica ni publica nada. */
29	export interface ArtifactFetcher {
30	  fetch(pinned: PinnedModelArtifact, destination: string): Promise<FetchOutcome>
31	}
32	
33	export type MaterializationOutcome =
34	  | { readonly status: 'cached' | 'fetched'; readonly path: string; readonly sha256: string }
35	  | { readonly status: 'rejected' | 'failed'; readonly reason: string }
36	
37	export interface MaterializationRequest {
38	  readonly artifact: CatalogArtifact
39	  readonly pinned: PinnedModelArtifact
40	  readonly cacheDir: string
41	  readonly fetcher: ArtifactFetcher
42	}
43	
44	/** La única ruta que un consumidor lee: el GGUF verificado, nombrado por su contenido. */
45	export function cachedArtifactPath(cacheDir: string, sha256: string): string {
46	  return join(cacheDir, `sha256-${sha256}.gguf`)
47	}
48	
49	/** El sha256 medido del archivo, o `undefined` si no existe. */
50	async function measuredSha256(path: string): Promise<string | undefined> {
51	  try {
52	    await stat(path)
53	  } catch {
54	    return undefined
55	  }
56	  return sha256OfFile(path)
57	}
58	
59	export async function materializeArtifact(request: MaterializationRequest): Promise<MaterializationOutcome> {
60	  const { artifact, pinned, cacheDir } = request
61	  if (pinned.blobDigest !== `sha256:${artifact.sha256}`) {
62	    return { status: 'rejected', reason: `el artefacto fijado apunta a ${pinned.blobDigest}, no al contenido sha256:${artifact.sha256} del catálogo` }
63	  }
64	  const path = cachedArtifactPath(cacheDir, artifact.sha256)
65	  // El sha256 que se devuelve es el MEDIDO sobre el archivo, no el declarado:
66	  // es la segunda igualdad de READY y no puede ser una copia del catálogo.
67	  const cached = await measuredSha256(path)
68	  if (cached === artifact.sha256) return { status: 'cached', path, sha256: cached }
69	
70	  await mkdir(cacheDir, { recursive: true })
71	  await rm(path, { force: true })
72	  const partial = join(cacheDir, `.partial-${artifact.sha256}-${process.pid}-${Date.now()}`)
73	  try {
74	    const fetched = await request.fetcher.fetch(pinned, partial)
75	    if (fetched.status !== 'fetched') return { status: 'failed', reason: fetched.reason }
76	    const actual = await sha256OfFile(partial)
77	    if (actual !== artifact.sha256) return { status: 'rejected', reason: `se descargó sha256:${actual}, el catálogo declara sha256:${artifact.sha256}` }
78	    await rename(partial, path)
79	    return { status: 'fetched', path, sha256: actual }
80	  } finally {
81	    await rm(partial, { force: true })
82	  }
83	}

  1	/**
  2	 * `ensureModel(name, deps)`: el reconciliador idempotente que deja disponible
  3	 * un modelo del catálogo en un runtime (TASK-THYROX-0729). No es
  4	 * `download()+install()`: cada paso mide el estado y actúa sólo si no es el
  5	 * pedido, así que la segunda llamada no descarga ni instala.
  6	 *
  7	 * Responde una sola pregunta —¿puede este runtime servir este modelo
  8	 * concreto?—. No decide GPU, instancia, residencia ni endpoint
  9	 * (TASK-THYROX-0703).
 10	 *
 11	 * READY exige tres digests iguales, cada uno medido: el sha256 del catálogo,
 12	 * el del GGUF materializado (el que `materializeArtifact` midió sobre el
 13	 * archivo antes de publicarlo en la caché) y el contenido que el runtime resuelve para el nombre después de
 14	 * cualquier instalación. Un instalador que responde `installed` y sirve otra
 15	 * cosa no deja READY. `downloaded` e `installed` dicen lo que ocurrió en esta
 16	 * llamada, no lo que se supone.
 17	 */
 18	import type { CatalogArtifact, ModelCatalogEntry } from '@thyrox/model-artifacts/catalogEntry.ts'
 19	import type { ModelArtifactResolver, PinnedModelArtifact } from '@thyrox/model-artifacts/modelArtifactResolver.ts'
 20	
 21	import { materializeArtifact, type ArtifactFetcher } from './modelArtifactCache.js'
 22	import type { InstalledModelState, ModelInstaller } from './modelInstaller.js'
 23	
 24	/** La parte del catálogo que el reconciliador consulta. */
 25	export interface CatalogLookup {
 26	  byName(name: string): ModelCatalogEntry | undefined
 27	}
 28	
 29	export interface EnsureModelDependencies {
 30	  readonly catalog: CatalogLookup
 31	  readonly resolver: ModelArtifactResolver
 32	  readonly fetcher: ArtifactFetcher
 33	  readonly installer: ModelInstaller
 34	  readonly cacheDir: string
 35	}
 36	
 37	/** Los tres digests cuya igualdad es READY. */
 38	export interface ReadinessEvidence {
 39	  readonly catalogSha256: string
 40	  readonly materializedSha256: string
 41	  /** Vacío si el runtime no resuelve el nombre: nunca coincide con un sha256. */
 42	  readonly runtimeSha256: string
 43	}
 44	
 45	/** Dónde se detuvo una reconciliación fallida. */
 46	export type EnsureStage = 'materialize' | 'install' | 'verify'
 47	
 48	export type EnsureOutcome =
 49	  | { readonly status: 'ready'; readonly name: string; readonly evidence: ReadinessEvidence; readonly downloaded: boolean; readonly installed: boolean }
 50	  | { readonly status: 'not_declared'; readonly name: string }
 51	  | { readonly status: 'not_materializable'; readonly name: string; readonly reason: string }
 52	  | { readonly status: 'failed'; readonly name: string; readonly stage: EnsureStage; readonly reason: string; readonly downloaded: boolean; readonly installed: boolean }
 53	
 54	/** Un GGUF verificado en la caché y lo que costó tenerlo. */
 55	interface Materialized {
 56	  readonly path: string
 57	  readonly sha256: string
 58	  readonly downloaded: boolean
 59	}
 60	
 61	/** Lo que el runtime resuelve tras reconciliar, y si hubo que instalar. */
 62	interface Reconciled {
 63	  readonly state: InstalledModelState | undefined
 64	  readonly installed: boolean
 65	}
 66	
 67	type StepResult<T> = { readonly ok: true; readonly value: T } | { readonly ok: false; readonly reason: string }
 68	
 69	export async function ensureModel(name: string, deps: EnsureModelDependencies): Promise<EnsureOutcome> {
 70	  const entry = deps.catalog.byName(name)
 71	  if (entry === undefined) return { status: 'not_declared', name }
 72	  const resolution = await deps.resolver.resolve(entry.artifact)
 73	  if (resolution.status !== 'resolved') return { status: 'not_materializable', name, reason: resolution.reason }
 74	
 75	  const materialized = await materialize(entry.artifact, resolution.pinned, deps)
 76	  if (!materialized.ok) return { status: 'failed', name, stage: 'materialize', reason: materialized.reason, downloaded: false, installed: false }
 77	  const { downloaded } = materialized.value
 78	
 79	  const reconciled = await reconcileRuntime(name, materialized.value, deps.installer)
 80	  if (!reconciled.ok) return { status: 'failed', name, stage: 'install', reason: reconciled.reason, downloaded, installed: false }
 81	  const { installed, state } = reconciled.value
 82	
 83	  const evidence = { catalogSha256: entry.artifact.sha256, materializedSha256: materialized.value.sha256, runtimeSha256: state?.contentSha256 ?? '' }
 84	  if (!isReady(evidence)) return { status: 'failed', name, stage: 'verify', reason: mismatchReason(name, evidence), downloaded, installed }
 85	  return { status: 'ready', name, evidence, downloaded, installed }
 86	}
 87	
 88	async function materialize(artifact: CatalogArtifact, pinned: PinnedModelArtifact, deps: EnsureModelDependencies): Promise<StepResult<Materialized>> {
 89	  const outcome = await materializeArtifact({ artifact, pinned, cacheDir: deps.cacheDir, fetcher: deps.fetcher })
 90	  if ('reason' in outcome) return { ok: false, reason: outcome.reason }
 91	  // `materializeArtifact` sólo devuelve `cached`/`fetched` tras medir el
 92	  // sha256 del archivo publicado: ese es el digest materializado.
 93	  return { ok: true, value: { path: outcome.path, sha256: outcome.sha256, downloaded: outcome.status === 'fetched' } }
 94	}
 95	
 96	/** Instala sólo si el runtime no resuelve el nombre al contenido materializado, y vuelve a inspeccionar. */
 97	async function reconcileRuntime(name: string, materialized: Materialized, installer: ModelInstaller): Promise<StepResult<Reconciled>> {
 98	  const current = await installer.inspect(name)
 99	  if (servesContent(current, materialized.sha256)) return { ok: true, value: { state: current, installed: false } }
100	  const outcome = await installer.install({ name, artifactPath: materialized.path, contentSha256: materialized.sha256 })
101	  if (outcome.status !== 'installed') return { ok: false, reason: outcome.reason }
102	  return { ok: true, value: { state: await installer.inspect(name), installed: true } }
103	}
104	
105	function servesContent(state: InstalledModelState | undefined, sha256: string): boolean {
106	  return state?.contentSha256 === sha256
107	}
108	
109	function isReady(evidence: ReadinessEvidence): boolean {
110	  return evidence.catalogSha256 === evidence.materializedSha256 && evidence.materializedSha256 === evidence.runtimeSha256
111	}
112	
113	function mismatchReason(name: string, evidence: ReadinessEvidence): string {
114	  const runtime = evidence.runtimeSha256 === '' ? 'nada' : `sha256:${evidence.runtimeSha256}`
115	  return `${name}: el catálogo declara sha256:${evidence.catalogSha256}, la caché tiene sha256:${evidence.materializedSha256} y el runtime resuelve ${runtime}`
116	}

  1	/**
  2	 * La frontera entre identidad de contenido e identidad de distribución
  3	 * (TASK-THYROX-0729).
  4	 *
  5	 * El catálogo declara QUÉ contenido necesita un modelo —`CatalogArtifact`:
  6	 * formato, sha256 y bytes del GGUF— y no sabe dónde vive. El
  7	 * `ModelArtifactResolver` responde DE DÓNDE se obtiene ese contenido: un
  8	 * artefacto permanente fijado por el digest de su manifest, en un registry y
  9	 * un repositorio. El registry no entra al catálogo.
 10	 *
 11	 * El índice de ubicaciones se busca sólo por digest de contenido: dos
 12	 * artefactos con el mismo repositorio o tag nunca se confunden, y un tamaño
 13	 * distinto del declarado no resuelve, porque entonces no es el mismo
 14	 * contenido. Es puro: no lee red; su persistencia es un JSON canónico con
 15	 * escritura atómica, como el catálogo.
 16	 */
 17	import { readFile, rename, rm, writeFile } from 'node:fs/promises'
 18	
 19	import type { CatalogArtifact } from './catalogEntry.js'
 20	
 21	/** Dónde se publicó un contenido: lo que registra una publicación verificada. */
 22	export interface ArtifactLocation {
 23	  /** 64 hex en minúsculas, sin prefijo: el sha256 del GGUF, igual al de `CatalogArtifact`. */
 24	  readonly contentSha256: string
 25	  readonly bytes: number
 26	  readonly registry: string
 27	  readonly repository: string
 28	  /** `sha256:<64 hex>`: el manifest que contiene la capa. */
 29	  readonly manifestDigest: string
 30	}
 31	
 32	/** La identidad de distribución inmutable de un artefacto de modelo. */
 33	export interface PinnedModelArtifact {
 34	  readonly registry: string
 35	  readonly repository: string
 36	  readonly manifestDigest: string
 37	  /** `sha256:<64 hex>`: la capa que es el GGUF. */
 38	  readonly blobDigest: string
 39	  readonly bytes: number
 40	}
 41	
 42	export type ArtifactResolution =
 43	  | { readonly status: 'resolved'; readonly pinned: PinnedModelArtifact }
 44	  | { readonly status: 'not_materializable'; readonly reason: string }
 45	
 46	export interface ModelArtifactResolver {
 47	  resolve(artifact: CatalogArtifact): Promise<ArtifactResolution>
 48	}
 49	
 50	export class InvalidArtifactLocationError extends Error {
 51	  constructor(field: string, value: unknown) {
 52	    super(`ubicación de artefacto inválida: ${field} = ${JSON.stringify(value)}`)
 53	    this.name = 'InvalidArtifactLocationError'
 54	  }
 55	}
 56	
 57	export class ArtifactLocationConflictError extends Error {
 58	  constructor(location: ArtifactLocation) {
 59	    super(`el contenido ${location.contentSha256} ya está registrado en ${location.repository}@${location.manifestDigest} con otro tamaño`)
 60	    this.name = 'ArtifactLocationConflictError'
 61	  }
 62	}
 63	
 64	const SHA256_HEX = /^[0-9a-f]{64}$/
 65	const OCI_DIGEST = /^sha256:[0-9a-f]{64}$/
 66	
 67	function validated(location: ArtifactLocation): ArtifactLocation {
 68	  if (!SHA256_HEX.test(location.contentSha256)) throw new InvalidArtifactLocationError('contentSha256', location.contentSha256)
 69	  if (!Number.isInteger(location.bytes) || location.bytes <= 0) throw new InvalidArtifactLocationError('bytes', location.bytes)
 70	  if (!location.registry) throw new InvalidArtifactLocationError('registry', location.registry)
 71	  if (!location.repository) throw new InvalidArtifactLocationError('repository', location.repository)
 72	  if (!OCI_DIGEST.test(location.manifestDigest)) throw new InvalidArtifactLocationError('manifestDigest', location.manifestDigest)
 73	  return {
 74	    bytes: location.bytes,
 75	    contentSha256: location.contentSha256,
 76	    manifestDigest: location.manifestDigest,
 77	    registry: location.registry,
 78	    repository: location.repository,
 79	  }
 80	}
 81	
 82	function sameManifest(a: ArtifactLocation, b: ArtifactLocation): boolean {
 83	  return a.contentSha256 === b.contentSha256 && a.registry === b.registry
 84	    && a.repository === b.repository && a.manifestDigest === b.manifestDigest
 85	}
 86	
 87	function orderKey(location: ArtifactLocation): string {
 88	  return [location.contentSha256, location.registry, location.repository, location.manifestDigest].join('\u0000')
 89	}
 90	
 91	/** Índice inmutable de ubicaciones, ordenado para que su JSON sea estable. */
 92	export class ArtifactLocationIndex {
 93	  private constructor(private readonly entries: readonly ArtifactLocation[]) {}
 94	
 95	  static of(locations: readonly ArtifactLocation[]): ArtifactLocationIndex {
 96	    return locations.reduce((index, location) => index.with(location), new ArtifactLocationIndex([]))
 97	  }
 98	
 99	  locations(): readonly ArtifactLocation[] {
100	    return this.entries
101	  }
102	
103	  /** Añade una ubicación; la misma otra vez no cambia nada, y el mismo manifest con otro tamaño rehúsa. */
104	  with(location: ArtifactLocation): ArtifactLocationIndex {
105	    const candidate = validated(location)
106	    const existing = this.entries.find(entry => sameManifest(entry, candidate))
107	    if (existing) {
108	      if (existing.bytes !== candidate.bytes) throw new ArtifactLocationConflictError(candidate)
109	      return this
110	    }
111	    return new ArtifactLocationIndex([...this.entries, candidate].sort((a, b) => orderKey(a).localeCompare(orderKey(b))))
112	  }
113	
114	  forContent(sha256: string): readonly ArtifactLocation[] {
115	    return this.entries.filter(entry => entry.contentSha256 === sha256)
116	  }
117	}
118	
119	export function createIndexedArtifactResolver(index: ArtifactLocationIndex): ModelArtifactResolver {
120	  return {
121	    async resolve(artifact) {
122	      const candidates = index.forContent(artifact.sha256)
123	      if (candidates.length === 0) {
124	        return { status: 'not_materializable', reason: `ningún artefacto permanente registrado contiene ${artifact.sha256}` }
125	      }
126	      const location = candidates.find(candidate => candidate.bytes === artifact.bytes)
127	      if (!location) {
128	        return { status: 'not_materializable', reason: `el contenido ${artifact.sha256} está registrado con otro tamaño que los ${artifact.bytes} bytes del catálogo` }
129	      }
130	      return {
131	        status: 'resolved',
132	        pinned: {
133	          registry: location.registry,
134	          repository: location.repository,
135	          manifestDigest: location.manifestDigest,
136	          blobDigest: `sha256:${location.contentSha256}`,
137	          bytes: location.bytes,
138	        },
139	      }
140	    },
141	  }
142	}
