144	/** Lee el índice; un archivo ausente es un índice vacío, uno inválido es un error con la ruta. */
145	export async function loadArtifactLocationIndex(path: string): Promise<ArtifactLocationIndex> {
146	  let text: string
147	  try {
148	    text = await readFile(path, 'utf8')
149	  } catch (error) {
150	    if ((error as NodeJS.ErrnoException).code === 'ENOENT') return ArtifactLocationIndex.of([])
151	    throw error
152	  }
153	  const document = JSON.parse(text) as { locations?: ArtifactLocation[] }
154	  if (!Array.isArray(document.locations)) throw new InvalidArtifactLocationError(`${path}: locations`, document.locations)
155	  return ArtifactLocationIndex.of(document.locations)
156	}
