158	/** Escribe el índice en un temporal hermano y lo renombra sobre la ruta. */
159	export async function saveArtifactLocationIndex(path: string, index: ArtifactLocationIndex): Promise<void> {
160	  const temporaryPath = `${path}.${process.pid}.${Date.now()}.tmp`
161	  try {
162	    await writeFile(temporaryPath, `${JSON.stringify({ locations: index.locations() }, null, 2)}\n`, { flag: 'wx' })
163	    await rename(temporaryPath, path)
164	  } finally {
165	    await rm(temporaryPath, { force: true })
166	  }
167	}
